// ============================================================================
// Paax — Custom Offline-First Service Worker
// ============================================================================
// This service worker enforces a CACHE-FIRST strategy for the app shell so
// that the Flutter UI loads instantly on cold start, even without a network
// connection (critical for Android TWA offline behaviour).
//
// Flutter's own `flutter_service_worker.js` is still generated by the build
// and handles versioned caching of compiled assets, but this worker sits in
// front of it and guarantees that the core shell is always available.
//
// NAVIGATION SHELL (v2, Cloudflare Pages fix)
// ---------------------------------------------------------------------------
// The shell is cached under the canonical ROOT URL (`./`), never `./index.html`.
// Static hosts such as Cloudflare Pages canonicalise `/index.html` with a 308
// redirect to `/`; a response obtained through a redirect carries
// `redirected === true`, and browsers REJECT such a response when a service
// worker returns it for a navigation request (ERR_FAILED on every visit after
// the first). v1 of this worker pre-cached `./index.html` and therefore broke
// every reload on Pages. v2 only ever stores and serves a navigation shell
// that is verified to be a successful, non-redirected, non-opaque HTML
// response, and bumps the cache namespace so a defective v1 entry can never
// be served again.
// ============================================================================

const CACHE_NAME = 'paax-app-shell-v2';

// Canonical app-shell URL. Resolved against the worker's own location, which
// is the registration scope root (`scope: './'` in index.html).
const SHELL_URL = './';

// Core app-shell resources that MUST be cached on install.
// After `flutter build web`, these files exist at the root of `build/web/`.
// NOTE: `./index.html` is intentionally NOT listed — see the header comment.
const APP_SHELL_URLS = [
  SHELL_URL,                  // index.html (via navigation to the root)
  './manifest.json',
  './flutter.js',
  './flutter_bootstrap.js',
  './main.dart.js',
  './favicon.png',
  './icons/Icon-192.png',
  './icons/Icon-512.png',
  './icons/Icon-maskable-192.png',
  './icons/Icon-maskable-512.png',
];

// Patterns that should ALWAYS be served cache-first.
// Matches: the app shell list above, plus any CanvasKit / font / asset files
// produced by the Flutter build.
const CACHE_FIRST_PATTERNS = [
  /\/(index\.html)?$/,                 // non-navigation GETs of the shell
  /\/main\.dart\.js/,
  /\/flutter\.js/,
  /\/flutter_bootstrap\.js/,
  /\/manifest\.json/,
  /\/favicon\.png/,
  /\/icons\//,
  /\/assets\//,                         // Flutter asset bundle (fonts, images)
  /\/canvaskit\//,                      // CanvasKit WASM/JS
  /\.js$/, // all JS chunks (deferred loading)
];

// ---------------------------------------------------------------------------
// Response validation
// ---------------------------------------------------------------------------

// A response may be stored as / served for a cached asset only when it is a
// real, successful, non-redirected response. Opaque responses (status 0) and
// opaque redirects are never cacheable here.
function isCacheableResponse(response) {
  return !!response
    && response.ok === true
    && response.redirected !== true
    && response.type !== 'opaque'
    && response.type !== 'opaqueredirect';
}

// The navigation shell must additionally be an HTML document: a cached JSON
// or JS body returned for a navigation would render as text.
function isUsableShellResponse(response) {
  if (!isCacheableResponse(response)) return false;
  const contentType = (response.headers && response.headers.get('content-type')) || '';
  return contentType.toLowerCase().indexOf('text/html') !== -1;
}

// Fetch a shell URL and store it only when it passes validation. Returns the
// fetched response (or null). Never throws: precaching is best-effort.
async function precache(cache, url) {
  try {
    const response = await fetch(url, { cache: 'no-cache', redirect: 'follow' });
    const valid = url === SHELL_URL
      ? isUsableShellResponse(response)
      : isCacheableResponse(response);
    if (!valid) {
      console.warn('[SW] Not caching', url, '(status', response && response.status,
        'redirected', response && response.redirected, ')');
      return null;
    }
    await cache.put(url, response.clone());
    return response;
  } catch (err) {
    console.warn('[SW] Could not precache', url, err);
    return null;
  }
}

// ---------------------------------------------------------------------------
// INSTALL — pre-cache the app shell
// ---------------------------------------------------------------------------
self.addEventListener('install', (event) => {
  // Skip waiting so the new SW activates immediately.
  self.skipWaiting();

  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      console.log('[SW] Pre-caching app shell');
      // Each URL is validated individually so one failure never blocks the
      // others and a redirected / failed response is never stored.
      return Promise.all(APP_SHELL_URLS.map((url) => precache(cache, url)));
    })
  );
});

// ---------------------------------------------------------------------------
// ACTIVATE — claim all clients + clean old caches
// ---------------------------------------------------------------------------
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((names) =>
      Promise.all(
        names
          .filter((name) => name !== CACHE_NAME)
          .map((name) => caches.delete(name))
      )
    ).then(() => self.clients.claim())
  );
});

// ---------------------------------------------------------------------------
// Navigation shell: cache-first, validated, revalidated in the background
// ---------------------------------------------------------------------------

async function serveShell(event) {
  const request = event.request;
  const cache = await caches.open(CACHE_NAME);
  const cached = await cache.match(SHELL_URL);

  if (isUsableShellResponse(cached)) {
    // Background revalidation — keep the shell fresh for the next visit so a
    // new release reaches returning users without clearing site data.
    event.waitUntil(precache(cache, SHELL_URL));
    return cached;
  }
  if (cached) {
    // Defensive: a stored entry that fails validation (e.g. redirected) must
    // never reach the browser as a navigation response.
    await cache.delete(SHELL_URL);
  }

  // Nothing usable cached: fetch the canonical root and store it if valid.
  const fresh = await precache(cache, SHELL_URL);
  if (fresh) return fresh;

  // The root itself did not yield a usable shell (unexpected host config):
  // fall through to the network for the original request so the browser
  // handles any redirect natively instead of receiving it from the worker.
  return fetch(request);
}

// ---------------------------------------------------------------------------
// FETCH — cache-first for app shell, stale-while-revalidate for the rest
// ---------------------------------------------------------------------------
self.addEventListener('fetch', (event) => {
  const request = event.request;

  // Only handle GET requests.
  if (request.method !== 'GET') return;

  // For navigation requests (HTML pages), ALWAYS serve the cached shell
  // (single-page app). This is the key to preventing the TWA's offline
  // fallback screen from appearing, and it also means deep links such as
  // /demo never depend on the host's redirect rules.
  if (request.mode === 'navigate') {
    event.respondWith(serveShell(event));
    return;
  }

  // Check if this URL matches a cache-first pattern.
  const url = new URL(request.url);
  const isCacheFirst = CACHE_FIRST_PATTERNS.some((p) => p.test(url.pathname));

  if (isCacheFirst) {
    // Cache-first: serve from cache immediately, update cache in background.
    event.respondWith(
      caches.match(request).then((cached) => {
        // Background revalidation — keep the cache fresh for next visit.
        const networkFetch = fetch(request)
          .then((response) => {
            if (isCacheableResponse(response)) {
              const clone = response.clone();
              caches.open(CACHE_NAME).then((c) => c.put(request, clone));
            }
            return response;
          })
          .catch(() => cached); // network failed, cache is the only option

        if (cached) event.waitUntil(networkFetch.catch(() => {}));
        return cached || networkFetch;
      })
    );
    return;
  }

  // Everything else (API calls, dynamic content): network-first.
  // We don't cache these — they'll naturally fail offline, which is expected.
});
